{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — Investment</title>
  <style>
    :root{--bg:#f7efe6;--card:#fff6f0;--accent:#8a5a3f;--muted:#6b6b6b;--ink:#2e2a25;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--ink);background-color:var(--bg);}
    body{background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:240px;}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(255,255,255,0.6));backdrop-filter:saturate(90%) blur(6px);}
    .brand{display:flex;flex-direction:column}
    .brand strong{font-size:18px;color:var(--accent)}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:980px;margin:28px auto;padding:20px}
    .hero{background:linear-gradient(180deg,rgba(138,90,63,0.06),transparent);border-radius:12px;padding:22px 20px;display:flex;gap:18px;align-items:center}
    .hero h1{margin:0;font-size:22px}
    .hero p{margin:6px 0 0;color:var(--muted)}
    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}
    .tier{background:var(--card);border-radius:10px;padding:18px;box-shadow:0 6px 18px rgba(42,30,24,0.06)}
    .tier h3{margin:0;color:var(--accent)}
    .price{font-size:20px;margin:12px 0;color:var(--ink)}
    .features{color:var(--muted);font-size:14px;margin:10px 0}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    .faq{margin-top:22px;background:var(--glass);padding:14px;border-radius:10px}
    footer{margin-top:28px;padding:18px;text-align:center;color:var(--muted)}
    /* reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    /* modal */
    .try{position:fixed;right:20px;bottom:20px;background:var(--accent);color:#fff;padding:12px 14px;border-radius:12px;box-shadow:0 8px 30px rgba(138,90,63,0.18);cursor:pointer}
    .modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px}
    .modal.open{display:flex}
    .dialog{width:100%;max-width:720px;background:#fff;border-radius:12px;padding:18px;box-shadow:0 12px 40px rgba(46,42,37,0.12);}
    .dialog header{display:flex;justify-content:space-between;align-items:center}
    .dialog .content{margin-top:10px}
    .breath-circle{width:160px;height:160px;border-radius:50%;margin:14px auto;background:radial-gradient(circle at 30% 30%,rgba(138,90,63,0.18),rgba(138,90,63,0.06));display:flex;align-items:center;justify-content:center}
    .pulse{width:28px;height:28px;border-radius:50%;background:var(--accent);transition:transform 3s ease-in-out}
    .pulse.expand{transform:scale(4)}
    @media(prefers-reduced-motion:reduce){.reveal{transition:none}.pulse{transition:none}}
    .journal textarea{width:100%;height:120px;padding:10px;border-radius:8px;border:1px solid #eee;font-size:14px}
    .buttons{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
  </style>
</head>
<body>
  <header>
    <div class='brand'>
      <strong>{{BUSINESS_NAME}}</strong>
      <small style='color:var(--muted)'>Memberships for steady habit change</small>
    </div>
    <nav>
      <a href='index.html'>Welcome</a>
      <a href='about.html'>Approach</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Journeys</a>
      <a href='pricing.html'>Investment</a>
      <a href='testimonials.html'>Stories</a>
      <a href='book.html'>Start</a>
      <a href='contact.html'>Connect</a>
    </nav>
  </header>
  <main>
    <section class='hero reveal' aria-labelledby='pricing-hero'>
      <div>
        <h1 id='pricing-hero'>Membership tiers built around habits, not quick fixes</h1>
        <p>Choose a path that matches your rhythm — steady frameworks, weekly touchpoints, and clear habit tracking.</p>
      </div>
      <div style='margin-left:auto;text-align:right'>
        <a class='cta' href='book.html'>{{PRIMARY_CTA_LABEL}}</a>
        <div class='note'>Monthly memberships with flexible commitments. Cancel any time.</div>
      </div>
    </section>

    <section class='tiers reveal' aria-label='Membership tiers'>
      <div class='tier'>
        <h3>Seedling</h3>
        <div class='price'>$29 / month</div>
        <div class='features'>Weekly guided check-ins · Habit templates · Private library</div>
        <a class='cta' href='book.html'>Start Seedling</a>
      </div>
      <div class='tier'>
        <h3>Root</h3>
        <div class='price'>$79 / month</div>
        <div class='features'>Weekly coaching, habit scaffolds, habit review tools, brother/sister cohort</div>
        <a class='cta' href='book.html'>Join Root</a>
      </div>
      <div class='tier'>
        <h3>Canopy</h3>
        <div class='price'>$149 / month</div>
        <div class='features'>Priority coaching slots · Custom framework building · Quarterly planning</div>
        <a class='cta' href='book.html'>Claim Canopy</a>
      </div>
    </section>

    <section class='faq reveal' aria-labelledby='pricing-faq'>
      <h4 id='pricing-faq'>How membership works</h4>
      <p class='note'>Membership centers on three pillars: micro-habits, weekly accountability, and frameworks you can repeat. No medical claims — just practical, trackable practice.</p>
      <div style='margin-top:10px'>
        <strong>Billing:</strong> Monthly with a single bill. Downgrades or cancellations take effect at the next cycle.<br>
        <strong>Commitment:</strong> Most members see steady improvement in routines in 8–12 weeks.
      </div>
    </section>

    <section class='reveal' style='margin-top:18px'>
      <h4>What's included</h4>
      <ul style='color:var(--muted)'>
        <li>Actionable frameworks for habit design</li>
        <li>Weekly short sessions focused on outcomes</li>
        <li>Workshop library and member-only content</li>
      </ul>
    </section>

    <section class='reveal' style='margin-top:14px'>
      <h4>Still deciding?</h4>
      <p class='note'>Try a 7-day condensed trial — includes our starter journaling prompts and a guided breathing session. Use the Try it now button.</p>
    </section>

    <footer>
      <div>Questions? Call {{PHONE}} or email <a href='mailto:{{EMAIL}}' style='color:var(--accent)'>{{EMAIL}}</a></div>
    </footer>
  </main>

  <button class='try' id='open-try'>Try it now</button>

  <div class='modal' id='modal'>
    <div class='dialog' role='dialog' aria-modal='true' aria-labelledby='dialog-title'>
      <header>
        <strong id='dialog-title'>Try a guided micro-practice</strong>
        <button id='close' aria-label='Close' style='background:none;border:none;font-size:16px;cursor:pointer'>✕</button>
      </header>
      <div class='content'>
        <p style='color:var(--muted)'>Select a short practice below. Each one is designed to be used anywhere and supports habit formation.</p>
        <div class='buttons'>
          <button data-mode='breath' class='cta' style='background:#fff;color:var(--accent);border:1px solid rgba(138,90,63,0.14)'>Breathing</button>
          <button data-mode='journal' class='cta' style='background:#fff;color:var(--accent);border:1px solid rgba(138,90,63,0.14)'>Journaling</button>
          <button data-mode='intention' class='cta' style='background:#fff;color:var(--accent);border:1px solid rgba(138,90,63,0.14)'>Intention</button>
        </div>
        <div id='practice' class='content' style='margin-top:12px'></div>
      </div>
    </div>
  </div>

  <script>
    // scroll reveal with prefers-reduced-motion support
    (function(){
      var prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var els = document.querySelectorAll('.reveal');
      if(prefersReduce){
        els.forEach(function(el){el.classList.add('visible');});
        return;
      }
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){
          if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target);} 
        });
      },{threshold:0.12});
      els.forEach(function(el){obs.observe(el);});
    })();

    // Try it now modal + micro-practices
    (function(){
      var modal = document.getElementById('modal');
      var open = document.getElementById('open-try');
      var close = document.getElementById('close');
      var practice = document.getElementById('practice');

      open.addEventListener('click',function(){modal.classList.add('open');renderMode('breath');});
      close.addEventListener('click',function(){modal.classList.remove('open');stopBreath();});
      modal.addEventListener('click',function(ev){if(ev.target===modal){modal.classList.remove('open');stopBreath();}});

      document.querySelectorAll('[data-mode]').forEach(function(btn){
        btn.addEventListener('click',function(){renderMode(btn.getAttribute('data-mode'));});
      });

      var breathTimer = null;
      function stopBreath(){if(breathTimer){clearInterval(breathTimer);breathTimer=null;}}

      function renderMode(mode){stopBreath();practice.innerHTML='';
        if(mode==='breath'){
          var wrap=document.createElement('div');wrap.className='breath';
          wrap.innerHTML="<div class='breath-circle' aria-hidden='true'><div class='pulse' id='pulse'></div></div><div style='text-align:center;color:var(--muted)'><p style='margin:0'>Follow the expansion: inhale 4s • hold 4s • exhale 6s</p></div>";
          practice.appendChild(wrap);
          var pulse = document.getElementById('pulse');
          var stage=0; // 0 expand (inhale+hold), 1 contract (exhale)
          function cycle(){
            stage = (stage+1)%2;
            if(stage===0){pulse.classList.add('expand');} else {pulse.classList.remove('expand');}
          }
          // start with expand for inhale
          pulse.classList.add('expand');
          breathTimer = setInterval(cycle,10000); // roughly matches 4+4+6 = 14 but simplified to comfortable rhythm
        }
        if(mode==='journal'){
          var j=document.createElement('div');j.className='journal';
          j.innerHTML = "<strong>Prompt:</strong><p style='color:var(--muted)'>Name one small action you can do today that would make tomorrow easier.</p><textarea placeholder='Write 3-6 sentences...'></textarea><div style='text-align:right;margin-top:8px'><button class='cta' id='saveJ'>Save</button></div>";
          practice.appendChild(j);
          document.getElementById('saveJ').addEventListener('click',function(){alert('Saved to local session. Keep this as a reminder.');modal.classList.remove('open');});
        }
        if(mode==='intention'){
          var it=document.createElement('div');it.className='intention';
          it.innerHTML = "<p style='color:var(--muted)'>Pick an intention for the day:</p>";
          var opts=['Focus','Gentleness','Clarity','Consistency'];
          opts.forEach(function(o){
            var b=document.createElement('button');b.textContent=o;b.className='cta';b.style.background='#fff';b.style.color='var(--accent)';b.style.border='1px solid rgba(138,90,63,0.08)';b.style.marginRight='8px';
            b.addEventListener('click',function(){alert('Intention set: '+o);modal.classList.remove('open');});
            it.appendChild(b);
          });
          practice.appendChild(it);
        }
      }
    })();
  </script>
</body>
</html>"} 
