      <div style='display:flex;justify-content:space-between;align-items:center'><strong>Guided micro-practice</strong><button id='close' style='border:none;background:none;cursor:pointer'>✕</button></div>
      <div id='practice' style='margin-top:12px;color:var(--muted)'></div>
