  <script>
    // Reveal with prefers-reduced-motion
    (function(){
      var prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var nodes = document.querySelectorAll('.reveal');
      if(prefersReduce){nodes.forEach(function(n){n.classList.add('visible');});return;}
      var observer = new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}});},{threshold:0.12});
      nodes.forEach(function(n){observer.observe(n);});
    })();

    // lightweight modal for Try it now (journal prompt)
    (function(){
      var open = document.getElementById('open-try');
      var modal = document.getElementById('modal');
      var close = document.getElementById('close');
      var practice = document.getElementById('practice');
      open.addEventListener('click',function(){modal.style.display='flex';render();});
      close.addEventListener('click',function(){modal.style.display='none';});
      function render(){practice.innerHTML = "<p style='margin:0'>Journaling prompt: What small action could you repeat for a week to build momentum?</p><textarea style='width:100%;margin-top:8px;height:80px;padding:8px;border-radius:8px;border:1px solid #eee'></textarea><div style='text-align:right;margin-top:8px'><button id='done' style='padding:8px 12px;border-radius:8px;background:#7a4f3a;color:#fff;border:none'>Done</button></div>";
        document.getElementById('done').addEventListener('click',function(){alert('Saved for this session.');modal.style.display='none';});
      }
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Book — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8f3ee;--accent:#8a5a3f;--muted:#6b6b6b;--card:#fffefc}
    body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial;background:var(--bg);color:#2b2723;background-image:url('assets/img/pattern.svg');background-size:200px}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:880px;margin:20px auto;padding:18px}
    .hero{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 12px 30px rgba(46,42,37,0.04)}
    .steps{display:flex;gap:12px;margin-top:14px}
    .step{flex:1;background:rgba(138,90,63,0.04);padding:12px;border-radius:8px}
    form{margin-top:16px;background:var(--card);padding:14px;border-radius:10px}
    label{display:block;font-size:13px;margin-top:8px;color:var(--muted)}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #efe6df;margin-top:6px}
    .submit{margin-top:12px;background:var(--accent);color:#fff;padding:10px 12px;border-radius:8px;border:none}
    .reveal{opacity:0;transform:translateY(16px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media(prefers-reduced-motion:reduce){.reveal{transition:none}}
    footer{margin-top:18px;color:var(--muted);text-align:center}
    .try{position:fixed;right:20px;bottom:20px;background:var(--accent);color:#fff;padding:10px 12px;border-radius:12px;cursor:pointer}
  </style>
</head>
<body>
  <header>
    <div><strong>{{BUSINESS_NAME}}</strong></div>
    <nav>
      <a href='index.html'>Welcome</a>
      <a href='about.html'>Approach</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Journeys</a>
      <a href='pricing.html'>Investment</a>
      <a href='testimonials.html'>Stories</a>
      <a href='book.html'>Start</a>
      <a href='contact.html'>Connect</a>
    </nav>
  </header>

  <main>
    <section class='hero reveal' aria-labelledby='book-hero'>
      <h1 id='book-hero'>Plan a concise conversation</h1>
      <p style='color:var(--muted)'>A short, structured call to map outcomes and see how membership supports your habits — no pressure, just clarity.</p>
      <div class='steps'>
        <div class='step'>1. Pick a time</div>
        <div class='step'>2. Share context</div>
        <div class='step'>3. Leave with a next step</div>
      </div>
    </section>

    <section class='reveal' style='margin-top:16px'>
      <h3>Quick booking</h3>
      <form id='bookForm' novalidate>
        <label for='name'>Your name</label>
        <input id='name' name='name' placeholder='First and last' required>

        <label for='email'>Email</label>
        <input id='email' name='email' type='email' placeholder='you@domain.com' required>

        <label for='goal'>Primary focus</label>
        <select id='goal' name='goal'>
          <option>Sleep & nightly routine</option>
          <option>Structured mornings</option>
          <option>Stress resilience practices</option>
          <option>Consistent movement</option>
          <option>Other</option>
        </select>

        <label for='notes'>Brief context (optional)</label>
        <textarea id='notes' name='notes' placeholder='Current routine, obstacles, what you hope to change' rows='4'></textarea>

        <button class='submit' type='submit'>Schedule a call</button>
        <div style='margin-top:8px;color:var(--muted);font-size:13px'>We will follow up to confirm a time. For urgent questions call {{PHONE}}.</div>
      </form>
    </section>

    <section class='reveal' style='margin-top:18px'>
      <h4>What to expect</h4>
      <p style='color:var(--muted)'>A 30-minute diagnostic focused on habits, practical constraints, and a suggested first two-week plan to test. No clinical advice — just structure you can use.</p>
    </section>

    <footer>
      <div>Prefer finding a slot yourself? Email <a href='mailto:{{EMAIL}}' style='color:var(--accent)'>{{EMAIL}}</a></div>
    </footer>
  </main>

  <button class='try' id='open-try'>Try it now</button>

  <div id='modal' style='display:none;position:fixed;inset:0;align-items:center;justify-content:center;padding:20px'>
    <div style='background:#fff;padding:16px;border-radius:12px;max-width:640px;margin:auto'>
      <div style='display:flex;justify-content:space-between;align-items:center'><strong>Guided practice</strong><button id='close' style='border:none;background:none;cursor:pointer'>✕</button></div>
      <div id='practice' style='margin-top:12px;color:var(--muted)'></div>
    </div>
  </div>

  <script>
    // Reveal with prefers-reduced-motion
    (function(){
      var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var items = document.querySelectorAll('.reveal');
      if(reduce){items.forEach(function(i){i.classList.add('visible');});return;}
      var io = new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}});},{threshold:0.12});
      items.forEach(function(i){io.observe(i);});
    })();

    // Booking form local handling
    document.getElementById('bookForm').addEventListener('submit',function(e){
      e.preventDefault();
      var name=document.getElementById('name').value||'Participant';
      alert('Thanks, '+name+" — we'll follow up on " + (document.getElementById('email').value||'your email') + '.');
      this.reset();
    });

    // Simple Try it now: three-mode micro-practices (breath/journal/intention)
    (function(){
      var open = document.getElementById('open-try');
      var modal = document.getElementById('modal');
      var close = document.getElementById('close');
      var practice = document.getElementById('practice');
      open.addEventListener('click',function(){modal.style.display='flex';renderPicker();});
      close.addEventListener('click',function(){modal.style.display='none';});
      function renderPicker(){practice.innerHTML="<div style='display:flex;gap:8px;flex-wrap:wrap'><button id='b' class='btn' style='padding:8px 10px;border-radius:8px;background:#fff;border:1px solid #eee'>Breathing</button><button id='j' class='btn' style='padding:8px 10px;border-radius:8px;background:#fff;border:1px solid #eee'>Journaling</button><button id='i' class='btn' style='padding:8px 10px;border-radius:8px;background:#fff;border:1px solid #eee'>Intention</button></div><div id="practiceArea" style="margin-top:12px;color:var(--muted)"></div>";
        document.getElementById('b').addEventListener('click',renderBreath);
        document.getElementById('j').addEventListener('click',renderJournal);
        document.getElementById('i').addEventListener('click',renderIntention);
      }
      var timer=null;
      function renderBreath(){var area=document.getElementById('practiceArea');area.innerHTML="<div style='text-align:center'><div style='width:120px;height:120px;margin:12px auto;border-radius:50%;background:radial-gradient(circle at 30% 30%,rgba(138,90,63,0.16),rgba(138,90,63,0.04));display:flex;align-items:center;justify-content:center'><div id='dot' style='width:20px;height:20px;border-radius:50%;background:var(--accent);transition:transform 3200ms ease'></div></div><p style='color:var(--muted)'>Inhale 4s • hold 4s • exhale 6s — continue for 2 cycles</p></div>";
        var dot=document.getElementById('dot');
        var expanded=false;dot.style.transform='scale(1)';
        if(timer){clearInterval(timer);} 
        timer = setInterval(function(){expanded=!expanded;dot.style.transform = expanded? 'scale(4)' : 'scale(1)';}, 10000);
      }
      function renderJournal(){clearInterval(timer);var area=document.getElementById('practiceArea');area.innerHTML="<strong>Prompt:</strong><p style='color:var(--muted)'>It takes one small, repeatable action to start a new routine. What is yours?</p><textarea style='width:100%;height:100px;padding:8px;border-radius:8px;border:1px solid #eee'></textarea><div style='text-align:right;margin-top:8px'><button id='save' style='padding:8px 12px;border-radius:8px;background:var(--accent);color:#fff;border:none'>Save</button></div>";
        document.getElementById('save').addEventListener('click',function(){alert('Saved locally. Use it as a reminder.');modal.style.display='none';});
      }
      function renderIntention(){clearInterval(timer);var area=document.getElementById('practiceArea');area.innerHTML="<p style='color:var(--muted)'>Select an intention:</p>";
        ['Focus','Gentleness','Consistency','Curiosity'].forEach(function(t){var b=document.createElement('button');b.textContent=t;b.style.marginRight='8px';b.style.padding='8px 10px';b.style.borderRadius='8px';b.style.border='1px solid #eee';b.addEventListener('click',function(){alert('Intention set: '+t);modal.style.display='none';});area.appendChild(b);});
      }
    })();
  </script>
</body>
